56	    // === 내부 헬퍼 함수 ===
57	
58	    // 현재 위치의 문자 코드 반환 (범위 초과 시 -1)
59	    @inline
60	    func (qp: *QParser) peek() -> i32 {
61	        if qp.pos >= qp.len {
