63	        }
64	        return char_at(qp.input, qp.pos);
65	    }
66	
67	    // 파서 커서 1칸 진진
68	    @inline
69	    func (qp: *QParser) advance() {
70	        if qp.pos < qp.len {
71	            qp.pos = qp.pos + 1;
72	        }
73	    }
