4	// 목표: 세션 내에서 여러 쿼리를 실행하고 히스토리를 추적
5	// 원리:
6	//   1. QuerySession: 고유 세션 ID + 쿼리 실행 엔진 + 히스토리 배열
7	//   2. QueryHistory: SQL문 + 결과 행 수 + 실행 성공 여부 + 타임스탐프
8	//   3. 히스토리 관리: 원형 버퍼 패턴 (최대 32개 유지)
9	// 구조:
10	//   - 상수 정의 (에러 코드, 제한값)
11	//   - QueryHistory, QuerySession 구조체
12	//   - 세션 생성 및 관리 함수 (new, execute, clear_history)
13	//   - 히스토리 조회 함수 (get_history, get_total, last_query)
14	//   - 메타데이터 함수 (stats)
15	// ============================================================================
16	
17	module query_session {
18	    // === 에러 코드 ===
19	    const QSESS_OK:           i32 = 0;
20	    const QSESS_ERR_FULL:     i32 = 180;
21	    const QSESS_ERR_NOTFOUND: i32 = 181;
22	
23	    // === 제한값 ===
24	    const MAX_QUERY_HISTORY: i32 = 32;
25	
26	    // === 데이터 구조체 ===
27	
28	    // 쿼리 히스토리 항목
29	    struct QueryHistory {
30	        sql:        string;
31	        result_cnt: i32;
32	        exec_ok:    bool;
33	        ts:         i64;
34	    }
35	
36	    // 쿼리 세션
37	    struct QuerySession {
38	        session_id:     i64;
39	        history:        [QueryHistory];
40	        hist_count:     i32;
41	        total_queries:  i32;
42	        runner:         query.Query;
43	    }
44	
45	    // === 세션 생성 ===
46	
47	    // 새로운 세션 생성
48	    func query_session_new(session_id: i64) -> QuerySession {
49	        return QuerySession{
50	            session_id:     session_id,
51	            history:        make([QueryHistory], MAX_QUERY_HISTORY),
52	            hist_count:     0,
53	            total_queries:  0,
54	            runner:         query.Query{
55	                table_ptr:   0,
56	                wheres:      make([query.WhereClause], query.MAX_WHERE),
57	                where_count: 0,
58	                order_by:    query.OrderBy{ col_idx: 0, asc: true, is_str: false },
59	                has_order:   false,
60	                limit:       query.MAX_RESULT_ROWS,
61	                offset:      0,
62	                agg_type:    query.AGG_NONE,
63	                agg_col:     0,
64	            },
65	        };
66	    }
67	
68	    // === 쿼리 실행 및 히스토리 기록 ===
69	
70	    // 쿼리 실행 및 히스토리 추가
71	    func (sess: *QuerySession) query_session_execute(t: schema.Table, sql: string) -> i32 {
72	        // 히스토리 오버플로우 체크
73	        if sess.hist_count >= MAX_QUERY_HISTORY {
74	            return QSESS_ERR_FULL;
75	        }
76	
77	        // 쿼리 엔진 실행
78	        let result = query.execute(t, sess.runner);
79	
80	        // 타임스탐프 생성 (간단화: total_queries를 타임스탐프처럼 사용)

