2	// FreeLang Physical Plan Module - 논리 계획 → 물리 계획 변환
3	// ============================================================================
4	// 목표: Logical Plan(planner.ExecPlan) → Physical Plan(연산자 파이프라인)
5	// 원리:
6	//   1. 논리 계획(PLAN_FULL_SCAN, PLAN_INDEX_EQ, etc.)을 물리 연산자로 변환
7	//   2. 연산자 파이프라인: TABLE_SCAN → FILTER → SORT → LIMIT
8	//   3. 비용 추정: 각 연산자별 O(n) 또는 O(log n)
9	// 구조:
10	//   - 상수 정의 (연산자 타입, 에러 코드)
11	//   - PhysicalOp, PhysicalPlan 구조체
12	//   - 계획 생성 및 변환 함수
13	//   - 파이프라인 연결 및 비용 계산
14	// ============================================================================
15	
16	module physical_plan {
17	    // === 연산자 타입 ===
18	    const PHYS_PLAN_TABLE_SCAN:  i32 = 1;   // 전체 테이블 스캔
19	    const PHYS_PLAN_INDEX_SCAN:  i32 = 2;   // 인덱스 기반 스캔
20	    const PHYS_PLAN_FILTER:      i32 = 3;   // WHERE 조건 필터
21	    const PHYS_PLAN_SORT:        i32 = 4;   // ORDER BY 정렬
22	    const PHYS_PLAN_LIMIT:       i32 = 5;   // LIMIT/OFFSET 페이징
23	    const PHYS_PLAN_AGGREGATE:   i32 = 6;   // 집계 함수 (COUNT/SUM/MAX/MIN)
24	    const PHYS_PLAN_NESTED_LOOP: i32 = 7;   // 중첩 루프 조인 (향후)
25	
26	    // === 집계 연산자 타입 ===
27	    const PHYS_AGG_NONE:  i32 = 0;
28	    const PHYS_AGG_COUNT: i32 = 1;
29	    const PHYS_AGG_SUM:   i32 = 2;
30	    const PHYS_AGG_MAX:   i32 = 3;
31	    const PHYS_AGG_MIN:   i32 = 4;
32	
33	    // === 에러 코드 ===
34	    const PHYS_OK:               i32 = 0;
35	    const PHYS_ERR_NOT_FOUND:    i32 = 90;
36	    const PHYS_ERR_INVALID_PLAN: i32 = 91;
37	    const PHYS_ERR_FULL:         i32 = 92;
38	
39	    // === 제한값 ===
40	    const MAX_OPS: i32 = 32;   // 최대 연산자 수 (파이프라인 깊이)
41	    const MAX_COLS: i32 = 16;
42	
43	    // === 데이터 구조체 ===
44	
45	    // 물리 연산자 (파이프라인 노드)
46	    struct PhysicalOp {
47	        op_type:     i32;      // PHYS_PLAN_* 상수
48	        col_idx:     i32;      // 연산 컬럼 인덱스 (-1 = 무관)
49	        agg_type:    i32;      // PHYS_AGG_* (집계 연산자용)
50	        limit_count: i32;      // LIMIT 행 수 (-1 = 무제한)
51	        next_op:     i32;      // 파이프라인 다음 연산자 인덱스 (-1 = 끝)
52	        is_used:     bool;     // 슬롯 사용 여부
53	    }
54	
55	    // 물리 계획 (연산자 파이프라인)
56	    struct PhysicalPlan {
57	        ops:         [PhysicalOp];    // 연산자 배열
58	        op_count:    i32;             // 사용 중인 연산자 수
59	        root_op_idx: i32;             // 루트 연산자 인덱스
60	    }
61	
62	    // === 초기화 함수 ===
63	
64	    // 새로운 물리 계획 생성
65	    func physical_plan_new() -> PhysicalPlan {
66	        let pp = PhysicalPlan{
67	            ops:         make([PhysicalOp], MAX_OPS),
68	            op_count:    0,
69	            root_op_idx: -1,
70	        };
71	
72	        // 모든 슬롯을 미사용으로 초기화
73	        let i = 0;
74	        for i = 0; i < MAX_OPS; i = i + 1 {
75	            pp.ops[i].is_used = false;
76	            pp.ops[i].next_op = -1;
77	        }
78	
79	        return pp;
80	    }

