206	    func (idx: *BTreeIndex) index_search(key: i64) -> (i64, bool) {
207	        let leaf_idx = idx.find_leaf(key);
208	        let leaf = idx.nodes[leaf_idx];
209	
210	        let i = 0;
211	        for i = 0; i < leaf.key_count; i = i + 1 {
212	            if leaf.keys[i] == key {
213	                return (leaf.row_ids[i], true);
214	            }
215	        }
216	        return (0, false);
