221	    // RANGE 검색: min_key <= key <= max_key
222	    func (idx: *BTreeIndex) index_range(min_key: i64, max_key: i64) -> ([i64], i32) {
223	        let result = make([i64], 1024);
224	        let result_count = 0;
225	
226	        // min_key가 속한 리프에서 시작
227	        let leaf_idx = idx.find_leaf(min_key);
228	
229	        // 리프 연결 리스트 순회
230	        for leaf_idx >= 0 && result_count < 1024 {
231	            let leaf = idx.nodes[leaf_idx];
232	            let i = 0;
233	            for i = 0; i < leaf.key_count && result_count < 1024; i = i + 1 {
234	                if leaf.keys[i] >= min_key && leaf.keys[i] <= max_key {
235	                    result[result_count] = leaf.row_ids[i];
236	                    result_count = result_count + 1;
237	                } else if leaf.keys[i] > max_key {
238	                    break;
239	                }
240	            }
241	
242	            // max_key 초과시 범위 스캔 종료
243	            if leaf.key_count > 0 && leaf.keys[leaf.key_count - 1] > max_key {
244	                leaf_idx = -1;
245	            } else {
246	                leaf_idx = leaf.next_leaf;
247	            }
248	        }
249	
250	        return (result, result_count);
251	    }
