208	    func executor_exec_filter(ex: *Executor, t: schema.Table, col_idx: i32, filter_val: i64, filter_op: i32) -> i32 {
209	        if col_idx < 0 || col_idx >= t.schema.col_count {
210	            return EXEC_ERR_INVALID_OP;
211	        }
