216	        // 각 행에 대해 필터 조건 적용
217	        for i = 0; i < ex.row_buf.count; i = i + 1 {
218	            let row_idx = ex.row_buf.row_indices[i];
219	
220	            // 컬럼 값 추출 (정수 컬럼으로 가정)
221	            let col_val = t.int_cols[col_idx * schema.MAX_ROWS + row_idx];
