226	            if filter_op == 2 && col_val > filter_val { match_found = true; }   // GT
227	            if filter_op == 3 && col_val < filter_val { match_found = true; }   // LT
228	            if filter_op == 4 && col_val >= filter_val { match_found = true; }  // GE
229	            if filter_op == 5 && col_val <= filter_val { match_found = true; }  // LE
230	
231	            if match_found {
