109	    // WHERE 조건 기반 실행 계획 선택
110	    func plan_query(q: query.Query, stats: TableStats, has_int_idx: bool, has_str_idx: bool) -> ExecPlan {
111	        // 기본 계획: 풀스캔
112	        let plan = ExecPlan{
113	            plan_type:  PLAN_FULL_SCAN,
114	            index_col:  -1,
115	            est_rows:   stats.row_count,
116	            cost:       stats.row_count,  // 비용 = 행 수
117	            error_code: PLAN_OK,
118	        };
119	
120	        // WHERE 절이 없으면 풀스캔
121	        if q.where_count == 0 {
122	            return plan;
123	        }
124	
125	        // 복합 WHERE 절 (AND)은 풀스캔 (간단화)
126	        if q.where_count > 1 {
127	            return plan;
128	        }
129	
130	        let where_clause = q.wheres[0];
131	        let col_idx = where_clause.col_idx;
132	
133	        // 컬럼 범위 검증
134	        if col_idx < 0 || col_idx >= stats.col_count {
135	            plan.error_code = PLAN_ERR_NO_STATS;
136	            return plan;
137	        }
138	
139	        // ===== INT 인덱스 고려 =====
140	        if has_int_idx && !where_clause.is_str {
141	            // EQUALITY 비교 (==)
142	            if where_clause.op == query.OP_EQ {
143	                plan.plan_type = PLAN_INDEX_EQ;
144	                plan.index_col = col_idx;
145	                plan.est_rows = 1;
146	                plan.cost = log_cost(stats.row_count) + 1;
147	                return plan;
148	            }
149	
150	            // RANGE 비교 (>, <, >=, <=)
151	            if where_clause.op == query.OP_GT || where_clause.op == query.OP_LT ||
152	               where_clause.op == query.OP_GE || where_clause.op == query.OP_LE {
153	                let range_est = range_estimate(stats, col_idx, where_clause.op, where_clause.int_val);
154	                plan.plan_type = PLAN_INDEX_RANGE;
155	                plan.index_col = col_idx;
156	                plan.est_rows = range_est;
157	                plan.cost = log_cost(stats.row_count) + range_est;
158	
159	                // 범위가 작으면 인덱스 사용, 크면 풀스캔 (휴리스틱)
160	                if plan.cost >= stats.row_count {
161	                    plan.plan_type = PLAN_FULL_SCAN;
162	                    plan.cost = stats.row_count;
163	                }
164	                return plan;
165	            }
166	        }
167	
168	        // ===== STR 인덱스 고려 =====
169	        if has_str_idx && where_clause.is_str {
170	            if where_clause.op == query.OP_LIKE {
171	                // LIKE: 접두어 매칭 (B+Tree 범위 스캔)
172	                let like_est = stats.row_count / 10;  // 휴리스틱: 전체의 1/10
173	                plan.plan_type = PLAN_INDEX_LIKE;
174	                plan.index_col = col_idx;
175	                plan.est_rows = like_est;
176	                plan.cost = log_cost(stats.row_count) + like_est;
177	                return plan;
178	            }
179	        }
180	
181	        // 기본: 풀스캔
182	        return plan;
183	    }
