91	    // SQL 문자열 → 파싱 → 계획 → 물리 계획 → 실행 → 결과
92	    func query_runner_execute(qr: *QueryRunner, t: schema.Table, sql: string) -> i32 {
93	        // 1단계: SQL 파싱
94	        qr.pq = query_parser.parse_query(sql, t);
95	        if qr.pq.has_error {
96	            qr.has_error = true;
97	            qr.error_code = QR_ERR_PARSE;
