107	        // 3단계: 쿼리 구조 생성 및 비용 기반 실행 계획 수립
108	        let q = query.query_table(t);
109	
110	        // WHERE 절 추가 (파서에서 추출된 정보 사용)
111	        if qr.pq.where_col_idx >= 0 {
112	            let col_type = t.schema.col_defs[qr.pq.where_col_idx].col_type;
113	
114	            // INT 컬럼 조건 추가
115	            if col_type == schema.COL_TYPE_INT {
116	                let op_val = qr.pq.where_op;
117	                // 파서의 연산자 코드를 query.fl의 코드로 매핑
118	                let mapped_op = op_val;  // 같은 코드 체계 사용
119	                q.where_int(qr.pq.where_col_idx, mapped_op, qr.pq.where_val_int);
120	            }
121	        }
122	
123	        // ORDER BY 설정
124	        if qr.pq.order_col_idx >= 0 {
125	            q.order_by_col(qr.pq.order_col_idx, !qr.pq.order_desc);
126	        }
127	
128	        // LIMIT 설정
129	        if qr.pq.limit_count > 0 {
130	            q.limit(qr.pq.limit_count);
131	        }
132	
133	        // 4단계: 비용 기반 실행 계획 생성
134	        qr.exec_plan = planner.plan_query(q, stats, false, false);
135	        if qr.exec_plan.error_code != planner.PLAN_OK {
136	            qr.has_error = true;
137	            qr.error_code = QR_ERR_PLAN;
138	            qr.stats.error_code = QR_ERR_PLAN;
139	            return QR_ERR_PLAN;
140	        }
141	        qr.stats.plan_type = qr.exec_plan.plan_type;
142	
143	        // 5단계: 논리 계획을 물리 계획으로 변환
144	        let phys_err = 0;
145	        (qr.phys_plan, phys_err) = physical_plan.physical_plan_from_logical(qr.exec_plan);
146	        if phys_err != physical_plan.PHYS_OK {
