274	            let j = 0;
275	            for j = 0; j < kw_len && matches; j = j + 1 {
276	                let sql_ch = to_upper_code(char_at(qp.input, i + j));
277	                let kw_ch = to_upper_code(char_at(kw, j));
278	                if sql_ch != kw_ch {
279	                    matches = false;
280	                }
281	            }
282	
283	            if matches {
284	                // 키워드 앞이 공백 또는 시작인지 확인
285	                let before_ok = (i == 0) || is_space_code(char_at(qp.input, i - 1));
286	                // 키워드 뒤가 공백 또는 끝인지 확인
287	                let after_ok = (i + kw_len >= qp.len) || is_space_code(char_at(qp.input, i + kw_len));
288	
289	                if before_ok && after_ok {
290	                    return i;
291	                }
292	            }
293	        }
294	
295	        return -1;
296	    }
